SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T7.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T5.FINPROD_MARKET_ID finprodId, T4.TARGET_FINPROD_ID targetFinprodId, IFNULL( T5.FINPROD_ABBR,T5.FINPROD_NAME) targetFinprodName, T3.BUSI_PS busiPs, T1.TRADE_MARKET tradeMarket, T1.ENTRUST_AMT/10000 totalAmt, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, IFNULL(T6.FINISH_AMT,0) finishAmt, IF(!ISNULL(T6.FINISH_AMT) ,case when T1.ENTRUST_AMT!=0 then ROUND(IFNULL(T6.FINISH_AMT,0)*100/(T1.ENTRUST_AMT*100),4) else 0 end,0) transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN ETR_ENTRUST_ADD T3 ON T1.ENTRUST_ID = T3.ENTRUST_ID INNER JOIN ETR_TARGET T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID INNER JOIN FIN_PRODUCT T5 ON T4.TARGET_FINPROD_ID = T5.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN SYS_USER T7 ON T1.INV_MANAGER_ID = T7.USER_NAME
AND T1.FINPROD_TYPE2 IN
#{bond,jdbcType=VARCHAR}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND (T4.TARGET_FINPROD_ID IN
null) OR T4.TARGET_FINPROD_ID IN (
#{prot,jdbcType=VARCHAR}
)
AND T1.CCY IN
#{prot}
AND T1.TRADE_MARKET IN
#{prot,jdbcType=VARCHAR}
AND T3.BUSI_PS = #{busiPs,jdbcType=VARCHAR}
AND T1.ENTRUST_STATUS IN
#{prot,jdbcType=VARCHAR}
AND T1.VDATE >=STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.MDATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
order by T1.ENTRUST_ID DESC

SELECT A.FINPROD_ID id, A.FINPROD_MARKET_ID text, A.FINPROD_ID, A.FINPROD_NAME, DATE_FORMAT(A.VDATE, '%Y-%m-%d') VDATE, DATE_FORMAT(A.MDATE, '%Y-%m-%d') MDATE, DATE_FORMAT(A.IDATE, '%Y-%m-%d') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, A.FINPROD_MARKET_ID, A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( select max(BASIS) as BASIS, FINPROD_ID from FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
group by FINPROD_ID ) basisData on A.FINPROD_ID = basisData.FINPROD_ID
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}
AND A.TRADE_MARKET = #{FINPROD_MARKET}
union select interf.SECID id, interf.SECID text, fin.FINPROD_ID, interf.SECNAME FINPROD_NAME, null, null, null, null, null, null, null, null, null, null from interf_payhsrcsecinfo interf left join fin_product fin on interf.SECID = fin.FINPROD_ID where SECID not in (select FINPROD_MARKET_ID from fin_product A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}
)
AND interf.SECID = #{initValue}
and ( interf.SECID LIKE CONCAT('%', CONCAT(#{search}, '%')) or interf.SECNAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND interf.MARKET = #{FINPROD_WIND_MARKET}
